command:
cd /testbed && printf '%s\n' '--- /opt/course-public-deps ---' && find /opt/course-public-deps -maxdepth 3 -type f -o -type l | head -100 && printf '%s\n' '--- pip inventory (filtered) ---' && python -m pip list 2>/dev/null | grep -Ei 'asgiref|sqlparse|pytz|psycopg|django|tzdata' || true && printf '%s\n' '--- system python deps ---' && /usr/bin/python3 - <<'EOF'
for mod in ('django','asgiref','sqlparse','pytz','psycopg2'):
    try:
        m=__import__(mod)
        print(mod, 'OK', getattr(m,'__file__',None))
    except Exception as e:
        print(mod, 'FAIL', repr(e))
EOF
printf '%s\n' '--- pip cache ---' && find /root/.cache/pip /opt -maxdepth 5 -type f \( -iname '*asgiref*' -o -iname '*sqlparse*' -o -iname '*pytz*' -o -iname '*psycopg*' \) 2>/dev/null | head -100
